PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
PRAGMA synchronous = NORMAL;
PRAGMA temp_store = MEMORY;
PRAGMA busy_timeout = 5000;
CREATE TABLE IF NOT EXISTS database_meta ( id INTEGER PRIMARY KEY AUTOINCREMENT, schema_version TEXT NOT NULL, app_version TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
INSERT INTO database_meta ( schema_version, app_version ) SELECT '1.0.0', '1.0.0' WHERE NOT EXISTS ( SELECT 1 FROM database_meta );
CREATE TABLE IF NOT EXISTS agent_session ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_uuid TEXT, title TEXT, goal TEXT NOT NULL, mode TEXT DEFAULT 'assist', status TEXT DEFAULT 'created', provider TEXT, model_name TEXT, started_at TEXT, finished_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE INDEX IF NOT EXISTS idx_agent_session_status ON agent_session(status);
CREATE INDEX IF NOT EXISTS idx_agent_session_created_at ON agent_session(created_at);
CREATE TABLE IF NOT EXISTS agent_step ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL, step_index INTEGER NOT NULL, state TEXT, action_name TEXT, action_json TEXT, reason TEXT, result_json TEXT, result_text TEXT, success INTEGER DEFAULT 0, verified INTEGER DEFAULT 0, verify_result TEXT, duration_ms INTEGER DEFAULT 0, error_message TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES agent_session(id) ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS idx_agent_step_session ON agent_step(session_id);
CREATE INDEX IF NOT EXISTS idx_agent_step_session_step ON agent_step ( session_id, step_index );
CREATE TABLE IF NOT EXISTS tool_execution ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER, step_id INTEGER, tool_name TEXT NOT NULL, tool_category TEXT, risk_level TEXT, parameters_json TEXT, success INTEGER DEFAULT 0, result_text TEXT, error_message TEXT, duration_ms INTEGER DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES agent_session(id) ON DELETE CASCADE, FOREIGN KEY(step_id) REFERENCES agent_step(id) ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS idx_tool_execution_session ON tool_execution(session_id);
CREATE INDEX IF NOT EXISTS idx_tool_execution_step ON tool_execution(step_id);
CREATE INDEX IF NOT EXISTS idx_tool_execution_tool ON tool_execution(tool_name);
CREATE TABLE IF NOT EXISTS uia_scan ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER, step_id INTEGER, scope TEXT, window_title TEXT, process_name TEXT, process_id INTEGER, window_x INTEGER, window_y INTEGER, window_width INTEGER, window_height INTEGER, total_elements INTEGER DEFAULT 0, clickable_elements INTEGER DEFAULT 0, elements_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES agent_session(id) ON DELETE CASCADE, FOREIGN KEY(step_id) REFERENCES agent_step(id) ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS idx_uia_scan_session ON uia_scan(session_id);
CREATE INDEX IF NOT EXISTS idx_uia_scan_step ON uia_scan(step_id);
CREATE TABLE IF NOT EXISTS screenshot_record ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER, step_id INTEGER, file_path TEXT NOT NULL, screenshot_type TEXT, monitor_index INTEGER, screen_x INTEGER, screen_y INTEGER, width INTEGER, height INTEGER, reason TEXT, vlm_analyzed INTEGER DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES agent_session(id) ON DELETE CASCADE, FOREIGN KEY(step_id) REFERENCES agent_step(id) ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS idx_screenshot_session ON screenshot_record(session_id);
CREATE INDEX IF NOT EXISTS idx_screenshot_created_at ON screenshot_record(created_at);
CREATE TABLE IF NOT EXISTS vision_analysis ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER, step_id INTEGER, screenshot_id INTEGER, provider TEXT, model_name TEXT, prompt_text TEXT, response_text TEXT, response_json TEXT, confidence REAL, success INTEGER DEFAULT 0, duration_ms INTEGER DEFAULT 0, error_message TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES agent_session(id) ON DELETE CASCADE, FOREIGN KEY(step_id) REFERENCES agent_step(id) ON DELETE CASCADE, FOREIGN KEY(screenshot_id) REFERENCES screenshot_record(id) ON DELETE SET NULL );
CREATE INDEX IF NOT EXISTS idx_vision_analysis_session ON vision_analysis(session_id);
CREATE INDEX IF NOT EXISTS idx_vision_analysis_step ON vision_analysis(step_id);
CREATE TABLE IF NOT EXISTS llm_request ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER, step_id INTEGER, role TEXT, provider TEXT, model_name TEXT, request_text TEXT, response_text TEXT, prompt_tokens INTEGER, completion_tokens INTEGER, total_tokens INTEGER, success INTEGER DEFAULT 0, duration_ms INTEGER DEFAULT 0, error_message TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES agent_session(id) ON DELETE CASCADE, FOREIGN KEY(step_id) REFERENCES agent_step(id) ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS idx_llm_request_session ON llm_request(session_id);
CREATE INDEX IF NOT EXISTS idx_llm_request_step ON llm_request(step_id);
CREATE INDEX IF NOT EXISTS idx_llm_request_role ON llm_request(role);
CREATE TABLE IF NOT EXISTS model_runtime ( id INTEGER PRIMARY KEY AUTOINCREMENT, role TEXT, provider TEXT, runtime TEXT, model_name TEXT, model_path TEXT, mmproj_path TEXT, host TEXT, port INTEGER, context_size INTEGER, gpu_layers INTEGER, threads INTEGER, status TEXT, pid INTEGER, started_at TEXT, stopped_at TEXT, error_message TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE INDEX IF NOT EXISTS idx_model_runtime_role ON model_runtime(role);
CREATE INDEX IF NOT EXISTS idx_model_runtime_status ON model_runtime(status);
CREATE TABLE IF NOT EXISTS application_log ( id INTEGER PRIMARY KEY AUTOINCREMENT, level TEXT NOT NULL, module TEXT, message TEXT NOT NULL, session_id INTEGER, step_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES agent_session(id) ON DELETE SET NULL, FOREIGN KEY(step_id) REFERENCES agent_step(id) ON DELETE SET NULL );
CREATE INDEX IF NOT EXISTS idx_application_log_level ON application_log(level);
CREATE INDEX IF NOT EXISTS idx_application_log_created_at ON application_log(created_at);
CREATE INDEX IF NOT EXISTS idx_application_log_session ON application_log(session_id);
CREATE TABLE IF NOT EXISTS config_history ( id INTEGER PRIMARY KEY AUTOINCREMENT, config_name TEXT NOT NULL, file_path TEXT, old_json TEXT, new_json TEXT, changed_by TEXT DEFAULT 'user', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE INDEX IF NOT EXISTS idx_config_history_name ON config_history(config_name);
CREATE TABLE IF NOT EXISTS uploaded_file ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER, original_name TEXT, file_path TEXT NOT NULL, extension TEXT, mime_type TEXT, file_size INTEGER, purpose TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES agent_session(id) ON DELETE SET NULL );
CREATE INDEX IF NOT EXISTS idx_uploaded_file_session ON uploaded_file(session_id);
CREATE TABLE IF NOT EXISTS user_interrupt ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER, step_id INTEGER, interrupt_type TEXT, mouse_x INTEGER, mouse_y INTEGER, key_code INTEGER, description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES agent_session(id) ON DELETE CASCADE, FOREIGN KEY(step_id) REFERENCES agent_step(id) ON DELETE SET NULL );
CREATE INDEX IF NOT EXISTS idx_user_interrupt_session ON user_interrupt(session_id);
CREATE TABLE IF NOT EXISTS permission_confirmation ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER, step_id INTEGER, action_type TEXT, command_text TEXT, risk_level TEXT, user_decision TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES agent_session(id) ON DELETE CASCADE, FOREIGN KEY(step_id) REFERENCES agent_step(id) ON DELETE SET NULL );
CREATE INDEX IF NOT EXISTS idx_permission_confirmation_session ON permission_confirmation(session_id);
CREATE TABLE IF NOT EXISTS runtime_statistics ( id INTEGER PRIMARY KEY AUTOINCREMENT, date_key TEXT NOT NULL, total_sessions INTEGER DEFAULT 0, successful_sessions INTEGER DEFAULT 0, failed_sessions INTEGER DEFAULT 0, total_agent_steps INTEGER DEFAULT 0, total_llm_requests INTEGER DEFAULT 0, total_vlm_requests INTEGER DEFAULT 0, total_uia_scans INTEGER DEFAULT 0, total_shell_calls INTEGER DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE UNIQUE INDEX IF NOT EXISTS idx_runtime_statistics_date ON runtime_statistics(date_key);
CREATE VIEW IF NOT EXISTS view_agent_session_summary AS SELECT s.id, s.session_uuid, s.title, s.goal, s.mode, s.status, s.provider, s.model_name, s.started_at, s.finished_at, s.created_at, COUNT(st.id) AS step_count, SUM( CASE WHEN st.success = 1 THEN 1 ELSE 0 END ) AS successful_step_count, SUM( CASE WHEN st.success = 0 THEN 1 ELSE 0 END ) AS failed_step_count FROM agent_session s LEFT JOIN agent_step st ON st.session_id = s.id GROUP BY s.id;
CREATE VIEW IF NOT EXISTS view_recent_errors AS SELECT id, level, module, message, session_id, step_id, created_at FROM application_log WHERE level IN ( 'ERROR', 'FATAL' ) ORDER BY id DESC;
CREATE VIEW IF NOT EXISTS view_recent_agent_steps AS SELECT st.id, st.session_id, s.goal, st.step_index, st.action_name, st.reason, st.success, st.verified, st.duration_ms, st.error_message, st.created_at FROM agent_step st LEFT JOIN agent_session s ON s.id = st.session_id ORDER BY st.id DESC;